{
  "title": "Discussion about living and working abroad in Slovakia and Austria",
  "topics": [
    {
      "id": "expatriates-in-slovakia",
      "title": "People living in Slovakia or abroad",
      "claims": [
        {
          "text": "There are members who live in Bratislava or elsewhere in Slovakia.",
          "evidence": [1]
        },
        {
          "text": "Some participants have friends or acquaintances in Austria and Poland.",
          "evidence": [3, 12, 13, 49]
        },
        {
          "text": "One user has been living in Slovakia for almost a year without speaking the local language.",
          "evidence": [43]
        }
      ]
    },
    {
      "id": "job-search-methods",
      "title": "How to find jobs abroad",
      "claims": [
        {
          "text": "LinkedIn is recommended as the main tool for job searching.",
          "evidence": [18]
        },
        {
          "text": "The user applied to about 100 vacancies and got only 3 interviews.",
          "evidence": [21]
        },
        {
          "text": "Job postings often require local language proficiency (B2 or B1).",
          "evidence": [46]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language expectations in the job market",
      "claims": [
        {
          "text": "German is commonly used, but many communications happen in English.",
          "evidence": [14, 15, 44]
        },
        {
          "text": "95% of vacancies state that a local language is required.",
          "evidence": [26]
        },
        {
          "text": "Some companies accept candidates with limited language skills if other criteria are met.",
          "evidence": [29]
        }
      ]
    },
    {
      "id": "salary-and-experience",
      "title": "Salary expectations and experience levels",
      "claims": [
        {
          "text": "Applicants with 2‑3 years of experience receive higher offers than those with less experience.",
          "evidence": [23, 35]
        },
        {
          "text": "Even with minimal experience, a candidate was invited to a mid‑level interview.",
          "evidence": [28]
        },
        {
          "text": "The speaker accepted the minimum salary to get a job quickly.",
          "evidence": [37]
        }
      ]
    },
    {
      "id": "relocation-considerations",
      "title": "Considerations for moving to another country",
      "claims": [
        {
          "text": "Language barrier in everyday life is a concern for newcomers.",
          "evidence": [47, 51, 52]
        },
        {
          "text": "Attending international tech events and Discord channels is suggested to improve English conversation skills.",
          "evidence": [56, 57]
        }
      ]
    }
  ],
